S.append(S2(c,B+' · 1','Đệ quy là gì?',card('Hàm tự gọi chính nó',P('Một bài toán lớn được <b>đưa về cùng bài toán nhưng nhỏ hơn</b>. Ví dụ: n! = n × (n − 1)!','Mọi hàm đệ quy cần hai phần:','<b>1. Trường hợp cơ sở</b>: đủ nhỏ để trả kết quả ngay, <b>không gọi đệ quy</b>.','<b>2. Bước đệ quy</b>: gọi lại chính nó với bài toán <b>nhỏ hơn</b>, tiến dần về cơ sở.')+WARN('Thiếu cơ sở hoặc không tiến về cơ sở: <b>đệ quy vô hạn</b> (RecursionError).')),CODE('def f(n):\n    if n <= 1:\n        return 1\n    return n * f(n - 1)\n\nprint(f(6))',24)+R('def f(n):\n    if n <= 1:\n        return 1\n    return n * f(n - 1)\nprint(f(6))','',26,'Giai thừa 6! = 720')))
