S.append(S2(c,B+' · 2','Ví dụ: tổng các chữ số',card('Phân tích',P('s(n) = (chữ số cuối) + s(phần còn lại).','<b>Cơ sở</b>: n = 0 → 0.','<b>Bước</b>: <code>n % 10 + s(n // 10)</code>.')),CODE('def s(n):\n    if n == 0:\n        return 0\n    return n % 10 + s(n // 10)\nprint(s(7385))',24)+R('def s(n):\n    if n == 0:\n        return 0\n    return n % 10 + s(n // 10)\nprint(s(7385))','',26,'Kết quả')+KEY('s(7385) = 5 + s(738) = 5 + 8 + s(73) = 5 + 8 + 3 + s(7) = 5 + 8 + 3 + 7 + s(0) = <b>23</b>.')))
S.append(S2(c,B+' · 2','Ví dụ: ƯCLN bằng đệ quy (Euclid)',card('Phân tích',P('<b>Cơ sở</b>: b = 0 → ƯCLN là a.','<b>Bước</b>: g(a, b) = g(b, a % b).')+KEY('Số lời gọi cỡ <b>log</b> của số nhỏ; ở Fibonacci liên tiếp là <b>trường hợp xấu nhất</b>.')),CODE('cnt = 0\ndef ucln(a, b):\n    global cnt\n    cnt += 1\n    return a if b == 0 else ucln(b, a % b)\nprint(ucln(48, 18), cnt)\ncnt = 0\nprint(ucln(89, 55), cnt)',22)+R('cnt = 0\ndef ucln(a, b):\n    global cnt\n    cnt += 1\n    return a if b == 0 else ucln(b, a % b)\nprint(ucln(48, 18), cnt)\ncnt = 0\nprint(ucln(89, 55), cnt)','',24,'(ƯCLN, số lời gọi)')))
S.append(S2(c,B+' · 2','Ví dụ: đổi sang nhị phân',card('Phân tích',P('<code>p(n) = p(n // 2) + str(n % 2)</code>: chữ số cuối là <b>n % 2</b>, phần đầu là nhị phân của <b>n // 2</b>.','<b>Cơ sở</b>: n = 0 → xâu rỗng.','Nhờ đệ quy, các chữ số <b>tự được ghép đúng thứ tự</b> (không cần đảo).')),CODE('def p(n):\n    if n == 0:\n        return ""\n    return p(n // 2) + str(n % 2)\nprint(p(37), bin(37)[2:])',24)+R('def p(n):\n    if n == 0:\n        return ""\n    return p(n // 2) + str(n % 2)\nprint(p(37), bin(37)[2:])','',26,'Kết quả')+KEY('37 = 100101₂: 37 → 18 dư 1 → 9 dư 0 → 4 dư 1 → 2 dư 0 → 1 dư 0 → 0 dư 1.')))
S.append(S2(c,B+' · 2','Ví dụ: lũy thừa nhanh (chia để trị)',card('Ý tưởng',P('x^n = (x^(n/2))² nếu n chẵn; = x × (x^(n−1)/2)² nếu n lẻ.','Chỉ cần <b>log₂ n</b> lần nhân thay vì n.')),CODE('def lt(x, n):\n    if n == 0:\n        return 1\n    h = lt(x, n // 2)\n    return h * h if n % 2 == 0 else h * h * x\nprint(lt(2, 10), lt(3, 13), lt(2, 100) == 2 ** 100)',22)+R('def lt(x, n):\n    if n == 0:\n        return 1\n    h = lt(x, n // 2)\n    return h * h if n % 2 == 0 else h * h * x\nprint(lt(2, 10), lt(3, 13), lt(2, 100) == 2 ** 100)','',24,'Kết quả')+KEY('Gọi đệ quy <b>một lần</b> rồi dùng lại kết quả h (không gọi hai lần!).')))
